def hook(ctx, nb):
    try:
        if ctx['action']['tool'] != 'click_action':
            return None
        val = ctx['action']['value_normalized']
    except Exception:
        return None
    if val != 'buy now':
        return None
    try:
        need = ctx['predicates']['required_options_unselected']
    except Exception:
        need = False
    if not need:
        return None
    return {'kind': 'block_and_prompt', 'message': 'Do not buy yet: this product page still has a required variant choice unselected. Choose the visible option that matches the instruction, such as the requested color, size, material, flavor, or pack count. If no visible option matches, use Back to Search instead of buying.'}
